package dev.veltraph.client.builder;
import dev.veltraph.client.config.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class Source95MenuContinuityTest {
 private Source95AcquisitionBinding binding(){return new Source95AcquisitionBinding(BuilderCropType.WHEAT,"Seeds","@vanilla",Set.of("Seeds"),Map.of("instant","Instant","stack","Stack"),500,100,30000);}
 private Source95AcquisitionAuthority.Scope scope(){return new Source95AcquisitionAuthority.Scope(new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),4,1);}
 private Source95AcquisitionAuthority partial(Source95AcquisitionAuthority.Scope s){var a=new Source95AcquisitionAuthority();a.bindOriginalAmount(s);a.issueLeg(binding(),s,64,192,127,10,0);a.acknowledgeLeg(s,191,64,192,true,11,true,true,1);return a;}
 @Test void legitimateSameOwnedAmountMenuSupportsSecondStack(){var s=scope();var a=partial(s);assertTrue(a.validateOwnedBoundary(s.player(),s.world(),s.connection(),s.owner(),s.menu(),s.screen(),s.menuId(),false,false));assertTrue(a.issueLeg(binding(),s,64,192,191,11,2));}
 @Test void sameTitleDifferentMenuIdOrObjectAndScreenCannotAuthorizeSecondPurchase(){var s=scope();for(int variant=0;variant<3;variant++){var a=partial(s);Object menu=variant==0?new Object():s.menu(),screen=variant==1?new Object():s.screen();int id=variant==2?5:s.menuId();assertFalse(a.validateOwnedBoundary(s.player(),s.world(),s.connection(),s.owner(),menu,screen,id,false,false));assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());assertFalse(a.issueLeg(binding(),s,64,192,191,11,2));assertEquals(64,a.acquired());}}
 @Test void nativeCloseReopenScreenABAStaysRevokedEvenAfterOriginalPointerRestored(){var s=scope();var a=partial(s);Object token=new Object();Source95MenuTransitions.attach(s.connection(),token);try{long floor=Source95MenuTransitions.floor();Source95MenuTransitions.received(s.connection(),Source95MenuTransitions.Kind.CONTAINER,s.player(),s.world(),new Object(),new Object(),5);Source95MenuTransitions.received(s.connection(),Source95MenuTransitions.Kind.CONTAINER,s.player(),s.world(),s.menu(),s.screen(),s.menuId());boolean changed=Source95MenuTransitions.changedAfter(s.connection(),token,floor);assertTrue(changed);assertFalse(a.validateOwnedBoundary(s.player(),s.world(),s.connection(),s.owner(),s.menu(),s.screen(),s.menuId(),changed,false));assertFalse(a.issueLeg(binding(),s,64,192,191,11,2));}finally{Source95MenuTransitions.detach(s.connection(),token);}}
 @Test void evenValidatedCustomStrategyCannotAdoptForeignPlayerWorldConnectionOrOwner(){var s=scope();for(int field=0;field<4;field++){var a=new Source95AcquisitionAuthority();a.bindOriginalAmount(s);assertFalse(a.validateOwnedBoundary(field==0?new Object():s.player(),field==1?new Object():s.world(),field==2?new Object():s.connection(),field==3?new Object():s.owner(),new Object(),new Object(),6,true,true));assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());}}
 @Test void sourceCustomNeedsItsActualIssuedSignAndConfirmationTransitionBeforeNewPaymentScope(){var s=scope();var a=new Source95AcquisitionAuthority();a.bindOriginalAmount(s);var confirm=new Source95AcquisitionAuthority.Scope(s.player(),s.world(),s.connection(),s.owner(),new Object(),new Object(),6,1);assertFalse(a.authorizeCustomConfirmation(confirm,null,null,10,11));assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());var valid=new Source95AcquisitionAuthority();valid.bindOriginalAmount(s);var sign=new Source95MenuTransitions.Event(11,Source95MenuTransitions.Kind.SIGN,s.player(),s.world(),s.connection(),new Object(),new Object(),0);var opened=new Source95MenuTransitions.Event(13,Source95MenuTransitions.Kind.CONTAINER,s.player(),s.world(),s.connection(),confirm.menu(),confirm.screen(),6);assertTrue(valid.authorizeCustomConfirmation(confirm,sign,opened,10,12));assertTrue(valid.issueLeg(binding(),confirm,128,384,127,10,0));}
}
